<script setup lang="ts">
const { data } = useFetch<{ enabled: boolean }>('/api/ai/status')
const open = ref(false), question = ref(''), busy = ref(false), error = ref('')
const messages = ref<{ role: 'user' | 'assistant'; content: string }[]>([])
async function ask() { if (!question.value.trim() || busy.value) return; busy.value = true; error.value = ''; const q = question.value; question.value = ''; const history = messages.value.slice(-10); messages.value.push({ role: 'user', content: q }); try { const r = await useApi()<{ answer: string }>('/ai/ask', { method: 'POST', body: { question: q, history } }); messages.value.push({ role: 'assistant', content: r.answer }) } catch(e) { error.value = errorMessage(e) } finally { busy.value = false } }
</script>
<template><USlideover v-if="data?.enabled" v-model:open="open" title="Ask Finance" description="Answers grounded in your billing data"><UButton icon="i-lucide-sparkles" variant="soft" label="Ask Finance" /><template #body><div class="space-y-4"><p v-if="!messages.length" class="text-muted">Try “Which invoices are overdue?” or “What is our monthly recurring revenue?”</p><div v-for="(m, i) in messages" :key="i" :class="m.role === 'user' ? 'bg-primary/10' : 'bg-elevated'" class="p-4 rounded-xl whitespace-pre-wrap text-sm"><p class="text-xs text-muted mb-2">{{ m.role === 'user' ? 'You' : 'Finance assistant' }}</p>{{ m.content }}</div><UAlert v-if="error" :title="error" color="error" /></div></template><template #footer><form class="flex gap-2 w-full" @submit.prevent="ask"><UInput v-model="question" placeholder="Ask about your finances…" class="flex-1" :maxlength="500" aria-label="Finance question" /><UButton type="submit" icon="i-lucide-arrow-up" :loading="busy" aria-label="Send question" /></form></template></USlideover></template>
